{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Compassionate, evidence-informed therapy in {{CITY}}, {{STATE}}. Telehealth and in-person options.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site-root">
  <header class="nav-wrap">
    <div class="container nav-inner">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" id="mainNav">
        <a href="about.html">About</a>
        <a href="specialties.html">Paths</a>
        <a href="approach.html">Approach</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html" class="cta-small">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <button id="menuToggle" class="menu-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO (editorial) -->
    <section class="hero container">
      <div class="hero-grid">
        <div class="hero-copy">
          <h1 class="eyebrow">Private practice therapy in {{CITY}}, {{STATE}}</h1>
          <h2 class="super">I help thoughtful people find steadiness through life's shifts.</h2>
          <p class="lead">I combine trauma-informed, relational, and cognitive approaches to help with anxiety, life transitions, relationships, and burnout. Sessions are confidential and collaborative — we work at a pace that fits you.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">Meet {{THERAPIST_NAME}}</a>
          </div>
          <p class="note">Licensed: {{LICENSE}} • Modalities: {{MODALITIES}}</p>
        </div>
        <figure class="hero-art">
          <img src="assets/img/hero.svg" alt="Decorative illustration of supportive connection">
          <figcaption class="visually-hidden">Illustration representing support and growth</figcaption>
        </figure>
      </div>
    </section>

    <!-- STORY / WHY I DO THIS -->
    <section class="story container" id="story">
      <div class="story-inner">
        <div class="avatar">
          <img src="assets/img/avatar.svg" alt="{{THERAPIST_NAME}} portrait illustration">
        </div>
        <div class="story-copy">
          <h3>A calm, pragmatic partnership</h3>
          <p>I started private practice to create a space where curiosity and steady support come together. My work is informed by years of clinical training and real-world experience helping people navigate anxiety, trauma responses, shaky relationships, and major life transitions. I value clarity, compassion, and practical tools that feel manageable in daily life.</p>
          <p class="small">Confidentiality: sessions are private and records are securely stored. If you are in crisis or feel unsafe, please call local emergency services or your crisis hotline — therapy is not an emergency service.</p>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK (how I work) -->
    <section class="framework container" id="framework">
      <h3>How we work together</h3>
      <p class="lede">A simple framework to guide our time: Safety, Clarity, and Adaptation.</p>
      <div class="cards">
        <article class="card">
          <h4>1. Safety</h4>
          <p>We begin by building enough safety in the relationship and in your nervous system so that honest work feels possible.</p>
        </article>
        <article class="card">
          <h4>2. Clarity</h4>
          <p>We map patterns and identify what keeps problems active — therapy includes reflection and concrete skills to test in life.</p>
        </article>
        <article class="card">
          <h4>3. Adaptation</h4>
          <p>We practice new responses that fit your goals: managing overwhelm, improving connection, or finding direction after change.</p>
        </article>
      </div>
    </section>

    <!-- PROGRAMS (services) -->
    <section class="programs container" id="programs">
      <h3>Paths I offer</h3>
      <p class="lede">Options shaped to different needs — each path includes individual sessions, progress check-ins, and a plan that fits your life.</p>
      <div class="program-grid">
        <div class="program">
          <h4>Stabilize & Regulate (Short-term)</h4>
          <p>Focused 8–12 week work for acute anxiety, stress, or when you need immediate tools to feel steadier.</p>
        </div>
        <div class="program">
          <h4>Reconnect (Relationship-focused)</h4>
          <p>Work on communication patterns, boundaries, and repair strategies for partners or individuals navigating relational pain.</p>
        </div>
        <div class="program">
          <h4>Deep Integration (Long-term)</h4>
          <p>Open-ended therapy for complex trauma, long-standing patterns, or meaning-making through life transitions.</p>
        </div>
      </div>
      <div class="program-cta">
        <a class="btn primary" href="book.html">Explore availability</a>
        <a class="btn ghost" href="specialties.html">See specialties</a>
      </div>
    </section>

    <!-- PRICING -->
    <section class="pricing container" id="pricing">
      <h3>Fees & insurance</h3>
      <p class="lede">Transparent pricing and flexible arrangements. I offer telehealth and in-person appointments. Sliding scale is available for a limited number of slots.</p>
      <div class="pricing-grid">
        <div class="price">
          <h4>Initial intake</h4>
          <p class="cost">$160</p>
          <p class="desc">60–75 minute assessment to map needs and collaboration plan.</p>
        </div>
        <div class="price">
          <h4>Standard session</h4>
          <p class="cost">$140</p>
          <p class="desc">50 minutes, regular weekly or biweekly sessions.</p>
        </div>
        <div class="price">
          <h4>Extended session</h4>
          <p class="cost">$200</p>
          <p class="desc">75 minutes for deeper processing or couples work.</p>
        </div>
      </div>
      <p class="small">Insurance: I do not bill insurance directly in most cases; I provide superbills you can submit for reimbursement if your plan covers out-of-network mental health. Scope & boundaries: I do not provide forensic evaluations, emergency services, or medication management.</p>
      <a class="btn ghost" href="fees.html">More about fees</a>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials container" id="testimonials">
      <h3>What people have said</h3>
      <div class="testi-wrap" id="testimonialsList">
        <blockquote class="testi">"I learned ways to calm down in the moment and to talk to my partner without escalating. {{THERAPIST_NAME}} was steady and practical." <cite>— L., 34</cite></blockquote>
        <blockquote class="testi">"The sessions helped me make sense of long-held patterns and try different choices. I felt respected and understood." <cite>— M., 42</cite></blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta container" id="cta">
      <div class="cta-inner">
        <h3>Ready to start?</h3>
        <p>Checking in is the first step. If you have questions about fit, reach out by phone or email and we'll find a time that works.</p>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Contact</a>
        </div>
        <p class="privacy-note">Confidential care provided. For safety: if you are in immediate danger, call your local emergency number. Therapy is not a crisis service.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <div>
        <p class="brand-small">{{BUSINESS_NAME}} — {{TAGLINE}}</p>
        <p class="contact">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav class="footer-nav">
        <a href="privacy.html">Privacy</a>
        <a href="faq.html">FAQ</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
    <p class="fineprint">Licensed: {{LICENSE}} • Modalities: {{MODALITIES}} • Serving {{CITY}}, {{STATE}}. Confidentiality and record-keeping practices explained during intake.</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
