{"path":"assets/css/styles.css","content":"/* Editorial, high-contrast styles for aura_editorial */
:root{--bg:#ffffff;--text:#0b1220;--muted:#606672;--accent:#0b67ff;--accent-2:#ff7a59;--card:#f6f8fb}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; color:var(--text); background:var(--bg); line-height:1.5}
.container{max-width:1100px;margin:0 auto;padding:28px}
.nav-wrap{border-bottom:1px solid #e6e9ef;background:#fff}
.nav-inner{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--text);text-decoration:none;font-size:18px}
.main-nav a{margin:0 10px;color:var(--muted);text-decoration:none}
.cta-small{background:var(--accent);color:#fff;padding:8px 12px;border-radius:6px;text-decoration:none}
.menu-toggle{display:none;background:none;border:0;font-size:20px}
.hero{padding:60px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:40px;align-items:center}
.eyebrow{font-size:14px;color:var(--accent-2);margin:0 0 8px}
.super{font-size:40px;line-height:1.03;margin:0 0 14px;font-weight:800;letter-spacing:-0.02em}
.lead{font-size:18px;color:var(--muted);margin:0 0 18px}
.hero-actions .btn{margin-right:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;text-decoration:none;border:1px solid transparent;font-weight:600}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border-color:#dce3f3;color:var(--text)}
.note{font-size:13px;color:var(--muted);margin-top:10px}
.hero-art img{width:100%;height:auto;display:block}
.story{padding:40px 0;border-top:1px solid #f0f3f8}
.story-inner{display:flex;gap:24px;align-items:center}
.avatar img{width:180px;height:auto;border-radius:8px;border:1px solid #eef2f8}
.story-copy h3{margin:0 0 10px;font-size:20px}
.small{font-size:13px;color:var(--muted)}
.framework{padding:40px 0}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.card{background:var(--card);padding:18px;border-radius:10px}
.programs{padding:40px 0;border-top:1px solid #f0f3f8}
.program-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.program{padding:16px;border:1px solid #eef2f8;border-radius:8px}
.program-cta{margin-top:18px}
.pricing{padding:40px 0}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.price{background:#fff;padding:16px;border-radius:8px;border:1px solid #eef2f8}
.cost{font-weight:700;font-size:20px;margin:6px 0}
.testimonials{padding:40px 0;border-top:1px solid #f0f3f8}
.testi-wrap{display:flex;flex-direction:column;gap:12px}
.testi{background:#fcfdff;border-left:4px solid var(--accent);padding:12px 14px;border-radius:6px}
.cta{padding:44px 0;background:linear-gradient(180deg,#f7fbff 0%,#fff 100%);border-top:1px solid #eef3fb}
.cta-inner{text-align:center}
.btn.large{padding:14px 20px;font-size:16px}
.site-footer{background:#091126;color:#cbd6f6;padding:24px 0;margin-top:30px}
.footer-inner{display:flex;justify-content:space-between;align-items:center}
.brand-small{font-weight:700}
.contact a{color:#cbd6f6;text-decoration:none}
.fineprint{font-size:12px;color:#a9b4d8;margin:12px auto 0;max-width:1100px}
.visually-hidden{position:absolute!important;height:1px;width:1px;overflow:hidden;clip:rect(1px,1px,1px,1px);white-space:nowrap}
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr;}
  .menu-toggle{display:block}
  .main-nav{display:none;position:absolute;right:16px;top:64px;background:#fff;padding:10px;border-radius:8px;box-shadow:0 8px 30px rgba(11,22,32,0.08)}
  .main-nav.show{display:flex;flex-direction:column}
  .story-inner{flex-direction:column;text-align:center}
  .cards,.program-grid,.pricing-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Minimal JS for interactivity: menu, smooth scroll, basic accessibility
document.addEventListener('DOMContentLoaded',function(){
  var menuToggle=document.getElementById('menuToggle');
  var mainNav=document.getElementById('mainNav');
  if(menuToggle){
    menuToggle.addEventListener('click',function(){
      mainNav.classList.toggle('show');
      var open=mainNav.classList.contains('show');
      menuToggle.setAttribute('aria-expanded',open? 'true':'false');
    });
  }

  // Smooth scroll for local links
  document.querySelectorAll('a[href^="#"]').forEach(function(anchor){
    anchor.addEventListener('click',function(e){
      e.preventDefault();
      var id=this.getAttribute('href').slice(1);
      var el=document.getElementById(id);
      if(el){ el.scrollIntoView({behavior:'smooth',block:'start'}); }
    });
  });

  // Basic analytics-free click handler for CTA redirection (keeps design private)
  var ctas=document.querySelectorAll('a[href*="{{PRIMARY_CTA_URL}}"]');
  ctas.forEach(function(a){
    a.addEventListener('click',function(){
      // small visual cue before navigation
      a.classList.add('clicked');
      setTimeout(function(){ window.location=a.getAttribute('href'); },180);
    });
  });
});
"} 
